16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.points(owner))")
32	    @Mapping(target = "membershipLevel",
33	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.level(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * The owner's canonical URL, formatted {@code '/api/owners/<id>'} where id is the owner's id.
43	     * Null when the owner has no id yet.
44	     */
45	    default String selfLink(Owner owner) {
46	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
51	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
52	     * telephone is recorded.
53	     */
54	    default String telephoneDisplay(Owner owner) {
55	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
56	                owner.getTelephone());
57	    }
58	
59	    /**
60	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
61	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
62	     * birth date is recorded.
63	     */
64	    default String ageBand(Owner owner) {
65	        if (owner.getBirthDate() == null) {
66	            return null;
67	        }
68	        java.time.LocalDate reference = owner.getRegistrationDate() != null
69	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
70	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
71	        if (age < 18) {
72	            return "MINOR";
73	        }
74	        if (age < 65) {
75	            return "ADULT";
76	        }
77	        return "SENIOR";
78	    }
79	
80	    /**
81	     * The owner's derived {@code identityKey} = SHA-256 hex over
82	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, the single key all
83	     * duplicate detection is expressed through.
84	     */
85	    default String identityKey(Owner owner) {
86	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
87	                owner.getTelephone(), owner.getEmail(), owner.getLastName());
88	    }
89	
90	    /**
91	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
92	     * {@code PHONE}.
93	     */
94	    default String contactPreference(Owner owner) {
95	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
96	    }
97	
98	    /**
99	     * The owner's salutation: the honorific {@code title}, a single space, then the {@code lastName}
100	     * when a title is present, or just the {@code lastName} when no title is given.
101	     */
102	    default String salutation(Owner owner) {
103	        String title = owner.getTitle();
104	        if (title == null || title.isBlank()) {
105	            return owner.getLastName();
106	        }
107	        return title + " " + owner.getLastName();
108	    }
109	
110	    default String initials(Owner owner) {
111	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
112	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
113	    }
114	
115	    /**
116	     * The owner's locality (region), read from the REGION component of the customerCode
117	     * ({@code <REGION>-<HASH8>}); see
118	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
119	     */
120	    default String locality(Owner owner) {
121	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
122	                owner.getCustomerCode());
123	    }
124	
125	    /**
126	     * The IANA timezone name for the owner's locality (region), from the fixed region-to-timezone
127	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane); see
128	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#timezoneOf}.
129	     * Null when the region is absent or unknown.
130	     */
131	    default String timezone(Owner owner) {
132	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.timezoneOf(
133	                owner.getCustomerCode());
134	    }
135	
136	    /**
137	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
138	     * Null when the customer code is absent.
139	     */
140	    default Integer checkDigit(Owner owner) {
141	        if (owner.getCustomerCode() == null) {
142	            return null;
143	        }
144	        String code = owner.getCustomerCode();
145	        int sum = 0;
146	        boolean dbl = true;
147	        for (int i = code.length() - 1; i >= 0; i--) {
148	            char c = code.charAt(i);
149	            if (c < '0' || c > '9') {
150	                continue;
151	            }
152	            int d = c - '0';
153	            if (dbl) {
154	                d *= 2;
155	                if (d > 9) {
156	                    d -= 9;
157	                }
158	            }
159	            sum += d;
160	            dbl = !dbl;
161	        }
162	        return (10 - (sum % 10)) % 10;
163	    }
164	
165	    /**
166	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of the fiscal
167	     * year the business-day-adjusted registrationDate falls in (fiscal year starting 1 July), e.g.
168	     * {@code FY27}. Null when the registration date is absent.
169	     */
170	    default String fiscalYear(Owner owner) {
171	        if (owner.getRegistrationDate() == null) {
172	            return null;
173	        }
174	        return String.format("FY%02d",
175	                org.springframework.samples.petclinic.rest.function.owner.OwnerMembership
176	                        .fiscalYearOf(owner.getRegistrationDate()) % 100);
177	    }
178	
179	    /**
180	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
181	     * digits of the fiscal year the registrationDate falls in (fiscal year starting 1 July), e.g.
182	     * {@code NSW-1A2B3C4D-M27}. Null when either the customer code or the registration date is absent.
183	     */
184	    default String membershipNumber(Owner owner) {
185	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
186	            return null;
187	        }
188	        return String.format("%s-M%02d", owner.getCustomerCode(),
189	                org.springframework.samples.petclinic.rest.function.owner.OwnerMembership
190	                        .fiscalYearOf(owner.getRegistrationDate()) % 100);
191	    }
192	
193	    Owner toOwner(OwnerDto ownerDto);
194	
195	    @Mapping(target = "id", ignore = true)
196	    @Mapping(target = "pets", ignore = true)
197	    Owner toOwner(OwnerFieldsDto ownerDto);
198	
199	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
200	
201	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
202	
203	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
204	        OwnerPageDto ownerPageDto = new OwnerPageDto();
205	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
206	        ownerPageDto.setPage(ownerPage.getNumber());
207	        ownerPageDto.setSize(ownerPage.getSize());
208	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
209	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
210	        return ownerPageDto;
211	    }
212	}
